INSERT INTO project_policies(id,name,description,permissions_bitmask) VALUES ('server-policy-owner','Server owner','All server permissions.',2147483647), ('server-policy-admin','Server administrator','Manage the server.',2130243583), ('server-policy-member','Server member','Participate in server conversations.',112);
