INSERT INTO role_policies(role_id,policy_id) SELECT id, CASE key WHEN 'owner' THEN 'server-policy-owner' WHEN 'admin' THEN 'server-policy-admin' ELSE 'server-policy-member' END FROM roles WHERE key IN ('owner','admin','member');
--> statement-breakpoint
UPDATE roles SET permissions_bitmask=0 WHERE key NOT IN ('owner','admin','member');
--> statement-breakpoint
CREATE TRIGGER role_default_policy AFTER INSERT ON roles WHEN NEW.key IN ('owner','admin','member') BEGIN INSERT INTO role_policies(role_id,policy_id) VALUES (NEW.id, CASE NEW.key WHEN 'owner' THEN 'server-policy-owner' WHEN 'admin' THEN 'server-policy-admin' ELSE 'server-policy-member' END); END;
